import math

CEILING_USD = 10.00
MAX_HOURS = 3.0          # hard validator bound; the plan is 2.0 h and the timeout guard is 2.5 h

def check_budget_limits(max_cost, max_hours):
    for name, value in (('max_cost', max_cost), ('max_hours', max_hours)):
        # Reject bools, NaN and infinity: NaN > 10.0 is False, so a plain comparison lets it through.
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0:
            raise ValueError(f'{name} must be a positive finite number, got {value!r}')
    if max_cost > CEILING_USD or max_hours > MAX_HOURS:
        raise ValueError(f'Budget violation: ${max_cost} / {max_hours}hrs exceeds ceiling')
    return True

def planned_cost(rate_per_hour, hours):
    return round(rate_per_hour * hours, 2)

assert planned_cost(0.60, 2.0) == 1.20       # A10G for the planned 2 hours
assert planned_cost(1.50, 2.0) == 3.00       # A100 for the planned 2 hours
assert planned_cost(1.50, 2.5) == 3.75       # worst case if the timeout guard fires
assert check_budget_limits(planned_cost(1.50, 2.5), 2.5)

for bad in ((10.01, 2.0), (5.0, 3.5), (float('nan'), 2.0), (5.0, float('inf')), (True, 2.0), (-1.0, 2.0)):
    try:
        check_budget_limits(*bad)
    except ValueError:
        continue
    raise AssertionError(f'accepted {bad}')
print('budget guard rejects every unsafe configuration')

