import json
import math
from pathlib import Path

class FinetunePreflightValidator:
    def __init__(self, dataset_path, baseline_path, budget_limit):
        self.dataset_path = Path(dataset_path)
        self.baseline_path = Path(baseline_path)
        self.budget_limit = budget_limit

    def verify_data(self):
        # Each JSONL row has input_ids and labels of equal length; at least one prompt token is
        # masked (-100) and at least one answer token is trained.
        rows = [json.loads(line) for line in self.dataset_path.read_text().splitlines() if line.strip()]
        bad = [i for i, r in enumerate(rows)
               if len(r['input_ids']) != len(r['labels'])
               or r['labels'][0] != -100
               or all(l == -100 for l in r['labels'])]
        return {'ok': bool(rows) and not bad, 'data_samples_count': len(rows), 'bad_rows': bad[:10]}

    def verify_baseline(self):
        if not self.baseline_path.exists():
            return {'ok': False, 'reason': 'baseline_results.json missing'}
        base = json.loads(self.baseline_path.read_text())
        acc = base.get('accuracy')
        ok = isinstance(acc, (int, float)) and 0 <= acc <= 1 and base.get('n', 0) > 0 and 'decoding' in base
        return {'ok': ok, 'baseline_score': acc, 'n': base.get('n')}

    def verify_budget(self):
        b = self.budget_limit
        ok = isinstance(b, (int, float)) and not isinstance(b, bool) and math.isfinite(b) and 0 < b <= 10.0
        return {'ok': ok, 'budget_limit': b}

    def validate(self):
        checks = {'data': self.verify_data(), 'baseline': self.verify_baseline(), 'budget': self.verify_budget()}
        verdict = 'GO' if all(c['ok'] for c in checks.values()) else 'NO-GO'
        return {'verdict': verdict, 'checks': checks,
                'baseline_score': checks['baseline'].get('baseline_score'),
                'data_samples_count': checks['data']['data_samples_count']}

# Fixture: two masked rows and a baseline from Activity 2.
Path('train.jsonl').write_text('\n'.join(json.dumps(r) for r in [
    {'input_ids': [101, 7, 8, 102, 55, 2], 'labels': [-100, -100, -100, -100, 55, 2]},
    {'input_ids': [101, 9, 102, 56, 57, 2], 'labels': [-100, -100, -100, 56, 57, 2]}]))
Path('baseline_results.json').write_text(json.dumps({'accuracy': 0.2, 'n': 10, 'decoding': {'temperature': 0.1}}))

report = FinetunePreflightValidator('train.jsonl', 'baseline_results.json', 10.0).validate()
assert report['verdict'] == 'GO' and report['data_samples_count'] == 2 and report['baseline_score'] == 0.2
# Every check must be able to say NO-GO; prove it with one failing input per check.
assert FinetunePreflightValidator('train.jsonl', 'baseline_results.json', 12.0).validate()['verdict'] == 'NO-GO'
assert FinetunePreflightValidator('train.jsonl', 'missing.json', 10.0).validate()['verdict'] == 'NO-GO'
assert FinetunePreflightValidator('train.jsonl', 'baseline_results.json', float('nan')).validate()['verdict'] == 'NO-GO'
print(json.dumps(report, indent=2))
